/**
 * Email address rules shared by every path that creates or looks up an account.
 *
 * Addresses are case-insensitive (ADR 0003): one spelling is stored and every
 * lookup compares in that spelling, so `Alice@Example.com` and
 * `alice@example.com` are the same account however either was typed.
 */

/** The stored spelling of an address: trimmed and lowercased. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/** Sign-up for an address that already has an account. */
export class EmailTakenError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly email: string) {
    super("An account with that email address already exists.");
    this.name = "EmailTakenError";
  }
}

