const RESET_TTL_MS = 60 * 60 * 1000;

/** The first workspace is named `<display name>'s workspace`. */
const WORKSPACE_NAME_SUFFIX = "'s workspace";

/**
 * Charges one attempt to the anonymous `bucketKey` and refuses it with
 * `RateLimitedError` when the bucket is empty.
 */
async function throttle(bucketKey: string): Promise<void> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, bucketKey);
  if (!verdict.allowed) {
    throw new RateLimitedError(bucketKey, verdict.resetAt);
  }
}

/**
 * `<display name>'s workspace`, with the display name shortened (whole
 * characters at a time) until the result fits the workspace name limit.
 */
function firstWorkspaceName(displayName: string): string {
  const room = ORG_NAME_MAX_LENGTH - WORKSPACE_NAME_SUFFIX.length;

  let shortened = "";
  for (const character of displayName) {
    if (shortened.length + character.length > room) break;
    shortened += character;
  }

  return `${shortened}${WORKSPACE_NAME_SUFFIX}`;
}
