 * address that already has an account creates nothing. The workspace slug is
 * derived up front and is never refused, so the writes that follow cannot
 * fail on the person's name.
 */
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  await throttle(REGISTER_BUCKET);

  const email = normalizeEmail(input.email);
  if (await userRepo.findUserByEmail(email)) {
    throw new EmailTakenError(email);
  }

  const passwordHash = await hashPassword(input.password);
  const slug = await deriveOrgSlug(input.name);

  let user: User;
  try {
    user = await userRepo.insertUser({ email, name: input.name, passwordHash });
  } catch (error) {
    // A concurrent sign-up for the same address won the unique index.
    if (await userRepo.findUserByEmail(email)) {
      throw new EmailTakenError(email);
    }
    throw error;
  }

  const org = await createOrganization(user.id, {
    name: firstWorkspaceName(input.name),
    slug,
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

