    const unsub = subscribe("member.joined", (e) => { joined.push(e); });
    for (const name of ["Admin", "Billing", "Support", "Taskflow", "Al", "J", "山田", "J", "Ω", "a".repeat(80), "a".repeat(80), "a".repeat(80)]) {
      const { user, org } = await register(input(name));
      expect(isValidSlug(org.slug), org.slug).toBe(true);
      expect(isReservedSlug(org.slug)).toBe(false);
      expect(org.name.endsWith("'s workspace")).toBe(true);
      expect(updateOrganizationSchema.safeParse({ orgId: org.id, name: org.name }).success, org.name).toBe(true);
      const sub = await subRepo.findSubscription(org.id);
      expect(sub?.status).toBe("active");
      expect(org.plan).toBe("free");
      console.log(JSON.stringify(name.slice(0, 10)), "->", org.slug, "|", org.name, "|", user.email);
    }
    unsub();
    expect(joined.length).toBe(12);
  });

  it("treats email case-insensitively", async () => {
    const { user } = await register(input("Casey", "Casey@Example.COM"));
    expect(user.email).toBe("casey@example.com");
    await expect(register(input("Casey", "casey@example.com"))).rejects.toMatchObject({ code: "conflict" });
    try { await register(input("Casey", "CASEY@example.com")); } catch (e) { console.log(toAppError(e)); }
    expect((await login({ email: "CASEY@EXAMPLE.com", password: PW, rememberMe: false })).user.id).toBe(user.id);
    expect((await userRepo.findUserByEmail("cAsEy@example.com"))?.id).toBe(user.id);
  });

  it("throttles sign-up", async () => {
    const cap = getBucketConfig("auth:register").capacity;
    for (let i = 0; i < cap; i++) await register(input(`Throttle ${i}`));
    const email = "throttled@example.com";
    const err = await register(input("Late", email)).catch((e) => e);
    expect(toAppError(err).code).toBe("rate_limited");
    console.log(toActionResult(err));
    expect(await userRepo.findUserByEmail(email)).toBeNull();
  });

  it("throttles sign-in and reset", async () => {
    await register(input("Logan", "logan@example.com"));
    const cap = getBucketConfig("auth:login").capacity;
    for (let i = 0; i < cap; i++) await login({ email: "logan@example.com", password: PW, rememberMe: false });
    const err = await login({ email: "logan@example.com", password: PW, rememberMe: false }).catch((e) => e);
    expect(toAppError(err).code).toBe("rate_limited");
    const rcap = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < rcap + 3; i++) await requestPasswordReset({ email: "logan@example.com" });
    const cerr = await confirmPasswordReset({ token: "x".repeat(32), password: PW, confirmPassword: PW }).catch((e) => e);
    expect(toAppError(cerr).code).toBe("rate_limited");
  });
});
